<?php declare(strict_types=1); require_once __DIR__.'/../src/helpers.php';
$routerId=(int)($_POST['router_id']??0); $items=json_decode((string)($_POST['items']??'[]'),true); if(!$routerId||!is_array($items)) jsonOut(['ok'=>false,'error'=>'Data interface tidak valid'],422);
$d=db(); $d->begin_transaction(); try{ $del=$d->prepare('DELETE FROM router_interfaces WHERE router_id=?');$del->bind_param('i',$routerId);$del->execute();$ins=$d->prepare('INSERT INTO router_interfaces(router_id,interface_name,display_name,enabled,sort_order) VALUES(?,?,?,?,?)');$order=0;foreach($items as $it){$n=trim((string)($it['name']??''));if($n==='')continue;$label=trim((string)($it['label']??''));$en=1;$ins->bind_param('issii',$routerId,$n,$label,$en,$order);$ins->execute();$order++;}$d->commit();jsonOut(['ok'=>true]);}catch(Throwable $e){$d->rollback();jsonOut(['ok'=>false,'error'=>$e->getMessage()],500);}
